sys_script_include.script:
var FleetSecurity = Class.create();
FleetSecurity.prototype = {
    // FLEET-30 (Slice A): helpers for the FLEET-62/63 ACL matrix
    ROLE: 'x_1850693_enterp_0.',
    OPEN_FOR_REQUESTER: ['DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'PENDING_ASSIGNMENT', 'WAITLISTED'],

    initialize: function() {
        this.uid = gs.getUserID();
        this._location = null;
    },

    has: function(role) {
        return gs.hasRole(this.ROLE + role);
    },

    myLocation: function() {
        if (this._location === null) {
            var u = new GlideRecord('sys_user');
            this._location = u.get(this.uid) ? (u.getValue('location') || '') : '';
        }
        return this._location;
    },

    isOwn: function(res) {
        return res.getValue('requested_by') == this.uid;
    },

    isDriver: function(res) {
        return res.getValue('assigned_driver') == this.uid;
    },

    isDirectReport: function(res) {
        return res.getValue('manager_approver') == this.uid;
    },

    isMyDepot: function(depotSysId) {
        return !!depotSysId && depotSysId == this.myLocation();
    },

    /** Reservation read (FLEET-62) */
    canReadReservation: function(res) {
        if (this.has('director')) {
            return true;
        }
        if (this.has('dispatcher') && this.isMyDepot(res.getValue('requested_depot'))) {
            return true;
        }
        return (this.has('requester') && this.isOwn(res)) ||
            (this.has('driver') && this.isDriver(res)) ||
            (this.has('approver') && this.isDirectReport(res));
    },

    /** Reservation write: requester own before assignment; dispatcher depot; director/admin all */
    canWriteReservation: function(res) {
        if (this.has('director')) {
            return true;
        }
        if (this.has('dispatcher') && this.isMyDepot(res.getValue('requested_depot'))) {
            return true;
        }
        return this.has('requester') && this.isOwn(res) &&
            this.OPEN_FOR_REQUESTER.indexOf(res.getValue('reservation_state')) > -1;
    },

    /** Reservation create: requester, dispatcher, director, admin */
    canCreateReservation: function() {
        return this.has('requester') || this.has('dispatcher');
    },

    /** Reservation delete: admin; dispatcher for own depot (not director); requester own DRAFT */
    canDeleteReservation: function(res) {
        if (this.has('admin')) {
            return true;
        }
        if (this.has('dispatcher') && !this.has('director') && this.isMyDepot(res.getValue('requested_depot'))) {
            return true;
        }
        return this.has('requester') && this.isOwn(res) && res.getValue('reservation_state') == 'DRAFT';
    },


    /** Vehicle read (FLEET-62): director all; dispatcher depot; others AVAILABLE + vehicles on own trips */
    canReadVehicle: function(v) {
        if (this.has('director')) {
            return true;
        }
        if (this.has('dispatcher') && this.isMyDepot(v.getValue('depot_location'))) {
            return true;
        }
        if (v.getValue('status') == 'AVAILABLE') {
            return true;
        }
        var r = new GlideRecord('x_1850693_enterp_0_reservation');
        r.addQuery('assigned_vehicle', v.getUniqueValue());
        r.addEncodedQuery('requested_by=' + this.uid + '^ORassigned_driver=' + this.uid);
        r.setLimit(1);
        r.query();
        return r.hasNext();
    },

    /** Vehicle write (FLEET-62): dispatcher own depot, director/admin all */
    canWriteVehicle: function(v) {
        return this.has('director') || (this.has('dispatcher') && this.isMyDepot(v.getValue('depot_location')));
    },


    /** Inspection read (FLEET-63): dispatcher, director, admin; requester and driver of the reservation */
    canReadInspection: function(ins) {
        if (this.has('dispatcher')) {
            return true;
        }
        var res = ins.reservation.getRefRecord();
        return res.isValidRecord() && (this.isOwn(res) || this.isDriver(res));
    },

    /** Inspection write/create (FLEET-63): dispatcher for own depot, director/admin */
    canWriteInspection: function(ins) {
        if (this.has('director')) {
            return true;
        }
        if (!this.has('dispatcher')) {
            return false;
        }
        var res = ins.reservation.getRefRecord();
        return !res.isValidRecord() || this.isMyDepot(res.getValue('requested_depot'));
    },


    /** Maintenance read (FLEET-63): dispatcher, director, tech, admin all; requester/driver own reports or trips; approver impacted dept */
    canReadMaintenance: function(m) {
        if (this.has('dispatcher') || this.has('director') || this.has('tech')) {
            return true;
        }
        if (m.getValue('reported_by') == this.uid) {
            return true;
        }
        var res = m.reservation.getRefRecord();
        return res.isValidRecord() && (this.isOwn(res) || this.isDriver(res) || this.isDirectReport(res));
    },

    /** Maintenance write (FLEET-63): dispatcher, director, admin full; tech the work orders assigned to them */
    canWriteMaintenance: function(m) {
        if (this.has('dispatcher') || this.has('director')) {
            return true;
        }
        return this.has('tech') && m.getValue('assigned_to') == this.uid;
    },
    type: 'FleetSecurity'
};
